def temps_propagation(voisins, s):
    distance = [-1] * len(voisins)   # -1 : pas encore contaminé
    distance[s] = 0
    file = [s]
    while file:
        sommet = file.pop(0)
        for v in voisins[sommet]:
            if distance[v] == -1:
                distance[v] = distance[sommet] + 1
                file.append(v)
    return max(distance)

